+// Artifact-only maximum-dissipation motor solve in the torque ball.
+fn motor_metric_solve(k: mat3x3<f32>, rhs: vec3<f32>) -> vec3<f32> {
+    let det = dot(k[0], cross(k[1], k[2]));
+    if (abs(det) <= 1.17549435e-35) { return vec3<f32>(0.0); }
+    return vec3<f32>(dot(rhs, cross(k[1], k[2])),
+        dot(cross(k[2], k[0]), rhs), dot(cross(k[0], k[1]), rhs)) / det;
+}
+
+fn spherical_motor_metric(ia: mat3x3<f32>, ib: mat3x3<f32>,
+    cdot: vec3<f32>, old: vec3<f32>, radius: f32) -> vec3<f32> {
+    if (radius <= 0.0) { return vec3<f32>(0.0); }
+    let raw = ia + ib;
+    // Input inertia may contain tiny upper/lower float32 asymmetry.
+    let k = 0.5 * (raw + transpose(raw));
+    let g = cdot - native_mul_mv(k, old);
+    var low = 0.0;
+    var high = length(g) / radius;
+    for (var iteration = 0u; iteration < 24u; iteration++) {
+        let mid = 0.5 * (low + high);
+        let shifted = k + mat3x3<f32>(vec3<f32>(mid,0.0,0.0),
+            vec3<f32>(0.0,mid,0.0),vec3<f32>(0.0,0.0,mid));
+        let x = motor_metric_solve(shifted, -g);
+        if (dot(x,x) > radius * radius) { low = mid; }
+        else { high = mid; }
+    }
+    let shifted = k + mat3x3<f32>(vec3<f32>(high,0.0,0.0),
+        vec3<f32>(0.0,high,0.0),vec3<f32>(0.0,0.0,high));
+    let x = spherical_clamp_vector_length(motor_metric_solve(shifted,-g),radius);
+    let feasible_old = spherical_clamp_vector_length(old,radius);
+    let candidate_value = 0.5 * dot(x,native_mul_mv(k,x)) + dot(g,x);
+    let old_value = 0.5 * dot(feasible_old,native_mul_mv(k,feasible_old)) + dot(g,feasible_old);
+    // Roundoff fallback preserves a feasible non-increasing objective.
+    return select(x,feasible_old,candidate_value > old_value);
+}
